action.code:
if (!root) return std::string();
if (!root->left && !root->right) {
    return std::string(encoded_length, root->ch);
}
std::string decoded;
std::shared_ptr<Node> cur = root;
std::size_t bits_processed = 0;
char byte;
while (bits_processed < static_cast<std::size_t>(encoded_length) && infile.get(byte)) {
    for (int i = 7; i >= 0 && bits_processed < static_cast<std::size_t>(encoded_length); --i) {
        bool bit = (static_cast<unsigned char>(byte) >> i) & 1u;
        cur = bit ? cur->right : cur->left;
        if (!cur) {
            // malformed data; stop decoding
            return decoded;
        }
        if (!cur->left && !cur->right) {
            decoded.push_back(cur->ch);
            cur = root;
        }
        ++bits_processed;
    }
}
return decoded;

